            min_child_weight=5,  # require more samples per leaf
            subsample=0.8,
            colsample_bytree=0.7,
            gamma=0.3,  # min split-loss gain — prunes low-value splits
            reg_alpha=0.1,  # L1: drives weak feature weights to zero
