    _champion_auc_same_window: Optional[float] = None
    try:
        if _FEATURE_FILE.exists():
            _champ_meta = json.loads(_FEATURE_FILE.read_text())
            _champion_auc_stored = _champ_meta.get("oos_auc")
    except Exception:
        pass

