        outcome_pct = r.get("outcome_pct")
        if action not in ("BUY", "SELL") or outcome_pct is None:
            continue
        label = 1 if (action == "BUY" and outcome_pct > 0) or (action == "SELL" and outcome_pct < 0) else 0
        X.append(_extract_features(r))
