    _nan_rate = _np.isnan(_X_arr).mean(axis=0)
    for _i, _rate in enumerate(_nan_rate):
        if _rate > 0.20:
            log.critical(
                f"[signal_ml] Feature '{_FEATURE_NAMES[_i]}' is {_rate:.1%} NaN — "
                "model training on degraded distribution. Check data pipeline."
            )

