    split = max(int(len(X) * _TRAIN_SPLIT), _MIN_SAMPLES)
    X_train, X_test = X[:split], X[split:]
    y_train, y_test = y[:split], y[split:]

    # Require ≥15 OOS samples before the AUC estimate is trustworthy enough for
