@_mutmut_mutated(mutants_x__load_resolved_signals_async__mutmut)
async def _load_resolved_signals_async() -> list[dict]:
    """Async DB load using the project's AsyncSessionLocal."""
    from database import AsyncSessionLocal
    from models import Signal
    from sqlalchemy import select

    async with AsyncSessionLocal() as db:
        rows = (
            await db.execute(
                select(
                    Signal.ticker,
                    Signal.action,
                    Signal.confidence,
                    Signal.raw_score,
                    Signal.sentiment,
                    Signal.sources,
                    Signal.rationale,
                    Signal.outcome_pct,
                    Signal.style,
                    Signal.session,
                    Signal.rr,
                    Signal.entry,
                    Signal.stop,
                    Signal.target,
                    Signal.price,
                    Signal.created_at,
                    Signal.change_pct,
                    Signal.days_to_earnings,
                    Signal.sector_etf,
                    Signal.rs_vs_sector,
                )
                .where(Signal.outcome_pct.isnot(None))
                .where(Signal.action.in_(["BUY", "SELL"]))
                .order_by(Signal.created_at)
            )
        ).all()

    return [
        {
            "ticker": r.ticker,
            "action": r.action,
            "confidence": r.confidence,
            "raw_score": r.raw_score,
            "sentiment": r.sentiment,
            "sources": r.sources or [],
            "rationale": r.rationale or [],
            "outcome_pct": r.outcome_pct,
            "style": r.style,
            "session": r.session,
            "rr": r.rr,
            "entry": r.entry,
            "stop": r.stop,
            "target": r.target,
            "price": r.price,
            "created_at": str(r.created_at) if r.created_at else "",
            "change_pct": r.change_pct,
            "days_to_earnings": r.days_to_earnings,
            "sector_etf": r.sector_etf,
            "rs_vs_sector": r.rs_vs_sector,
        }
        for r in rows
    ]


